s.RegisterAction<string>($"{Name}::Playlist::PlayByName", s => s.WithLabel("File name/path"), name => WhenConnected(() =>
        {
            var playlist = ScriptPlaylist;
            if (playlist == null)
                return;

            var index = playlist.FindIndex(name);
            if (index >= 0)
                WriteMessage(new PlayScriptAtIndexMessage(index));
        }));

s.RegisterAction<DeviceAxis>($"MotionProvider::{name}::IsLooping::Toggle",
            s => s.WithLabel("Target axis").WithItemsSource(DeviceAxis.All),
            axis => UpdateProperty(axis, p => p.IsLooping = !p.IsLooping));

s.RegisterAction<DeviceAxis, bool>($"MotionProvider::{name}::Reset",
            s => s.WithLabel("Target axis").WithItemsSource(DeviceAxis.All),
            s => s.WithLabel("Request sync").WithDefaultValue(true),
            (axis, sync) => UpdateProperty(axis, p => {
                if (sync)
                    p.RequestSync();
                p.ResetState(true);
            }));

s.RegisterAction<DeviceAxis, DeviceAxis>("Axis::LinkAxis::Set",
            s => s.WithLabel("Source axis").WithItemsSource(DeviceAxis.All),
            s => s.WithLabel("Target axis").WithItemsSource(DeviceAxis.All),
            (source, target) =>
            {
                if (source == null || source == target)
                    return;

                AxisSettings[source].LinkAxis = target;
                ReloadAxes(source);
            });

s.RegisterAction<string>("Shortcut::Enabled::Toggle",
            s => s.WithLabel("Target shortcut name"),
            shortcutName => UpdateSettings(shortcutName, s => s.Enabled = !s.Enabled));
